package kik.i18n;
import android.app.*;import android.os.*;import android.graphics.*;import android.graphics.drawable.BitmapDrawable;import android.widget.*;import android.view.*;import java.util.concurrent.*;import org.json.*;
/** Remote-friendly device authorization; the password is entered only on the user's phone/computer. */
public final class SyncActivity extends Activity {
 private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newSingleThreadExecutor();private TextView status,code,address;private ImageView qr;private Button connect,refresh,disconnect;private String profile,deviceCode;private volatile int generation;private volatile boolean destroyed;private long expires;
 private int dp(int n){return Ui.dp(this,n);}private TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextColor(0xfff7f7f8);t.setTextSize(size);return t;}
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.screen(this);profile=ProfileStore.current(this);ScrollView scroll=new ScrollView(this);LinearLayout content=new LinearLayout(this);content.setOrientation(1);content.setPadding(dp(48),dp(34),dp(48),dp(30));scroll.addView(content);setContentView(scroll);
  TextView title=text("Один профіль • усі пристрої",28);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);content.addView(title);TextView intro=text("Профіль на TV: "+ProfileStore.nameOf(this,profile)+"\nІсторія, серії, позиція перегляду, мій список і вподобання синхронізуються з сайтом.",17);intro.setPadding(0,dp(16),0,dp(18));content.addView(intro);
  status=text("",16);content.addView(status);LinearLayout pairing=new LinearLayout(this);pairing.setGravity(Gravity.CENTER_VERTICAL);content.addView(pairing);LinearLayout typed=new LinearLayout(this);typed.setOrientation(1);pairing.addView(typed);address=text(UpdateConfig.WEB_ORIGIN,20);address.setPadding(0,dp(14),0,dp(8));typed.addView(address);code=text("",40);code.setTypeface(Typeface.MONOSPACE,Typeface.BOLD);code.setPadding(0,0,0,dp(12));typed.addView(code);
  qr=new ImageView(this);qr.setVisibility(View.GONE);LinearLayout.LayoutParams qp=new LinearLayout.LayoutParams(dp(200),dp(200));qp.leftMargin=dp(40);qp.bottomMargin=dp(12);pairing.addView(qr,qp);
  connect=Ui.pill(this,"Підключити профіль",true);content.addView(connect,new LinearLayout.LayoutParams(dp(360),dp(50)));connect.setOnClickListener(v->pair());
  refresh=Ui.pill(this,"Синхронізувати зараз",false);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(360),dp(50));lp.topMargin=dp(12);content.addView(refresh,lp);refresh.setOnClickListener(v->{CloudSync.now(this);status.setText("Синхронізація…");main.postDelayed(this::render,2200);});
  disconnect=Ui.pill(this,"Від’єднати профіль",false);content.addView(disconnect,lp);disconnect.setOnClickListener(v->Ui.dialog(this).setTitle("Від’єднати TV від сайту?").setMessage("Завантажена історія залишиться на TV. Нові зміни більше не синхронізуватимуться.").setNegativeButton("Скасувати",null).setPositiveButton("Від’єднати",(d,w)->{CloudSync.disconnect(this,profile);render();}).show());
  Button back=Ui.pill(this,"Готово",false);content.addView(back,lp);back.setOnClickListener(v->finish());render();connect.requestFocus();
 }
 private void render(){if(destroyed)return;boolean linked=CloudSync.linked(this,profile);status.setText(linked?"Підключено: "+CloudSync.profileName(this,profile)+"\n"+CloudSync.status(this,profile):"Підключіть цей профіль до облікового запису на сайті.");connect.setText(linked?"Підключити інший профіль":"Підключити профіль");connect.setEnabled(true);refresh.setVisibility(linked?View.VISIBLE:View.GONE);disconnect.setVisibility(linked?View.VISIBLE:View.GONE);if(linked){code.setText("");hideQr();address.setText(UpdateConfig.WEB_ORIGIN);}}
 private void pair(){int gen=++generation;deviceCode=null;connect.setEnabled(false);status.setText("Отримання коду…");code.setText("");hideQr();io.execute(()->{try{JSONObject result=CloudSync.request("/api/pair/start",new JSONObject(),null);main.post(()->{if(destroyed||gen!=generation)return;deviceCode=result.optString("device_code");expires=SystemClock.elapsedRealtime()+result.optInt("expires_in",600)*1000L;String value=result.optString("user_code");code.setText(value.substring(0,4)+" "+value.substring(4));address.setText(UpdateConfig.WEB_ORIGIN);showQr(UpdateConfig.WEB_ORIGIN+"/pair?code="+value);status.setText("1. Наведіть камеру телефона на QR-код — сайт відкриється сам.\n2. Увійдіть, виберіть спільний профіль і підтвердьте.\nБез камери: відкрийте сайт, натисніть «Прив’язати TV» та введіть код. Код діє 10 хвилин.");connect.setEnabled(true);connect.setText("Отримати інший код");poll(gen);});}catch(Exception e){main.post(()->{if(!destroyed&&gen==generation){render();status.setText("Не вдалося отримати код. Перевірте підключення до інтернету.");}});}});}
 private void poll(int gen){if(destroyed||gen!=generation||deviceCode==null)return;if(SystemClock.elapsedRealtime()>expires){status.setText("Код прострочений. Отримайте новий.");code.setText("");hideQr();return;}final String secret=deviceCode;io.execute(()->{try{JSONObject result=CloudSync.request("/api/pair/poll",new JSONObject().put("device_code",secret),null);if(!result.optBoolean("pending")){if(destroyed||gen!=generation||ProfileStore.nameOf(this,profile)==null)return;CloudSync.bind(this,profile,result.getString("token"),result.getJSONObject("profile"));main.post(()->{if(!destroyed&&gen==generation){deviceCode=null;code.setText("");render();main.postDelayed(this::render,3000);}});return;}}catch(Exception ignored){}main.postDelayed(()->poll(gen),3000);});}
 /** One pixel per module plus the 4-module quiet zone; nearest-neighbour scaling keeps the edges sharp on the projector. */
 private void showQr(String url){QrCode q=QrCode.encode(url);int n=q.size+8;int[] px=new int[n*n];for(int y=0;y<n;y++)for(int x=0;x<n;x++){int mx=x-4,my=y-4;px[y*n+x]=mx>=0&&my>=0&&mx<q.size&&my<q.size&&q.dark(mx,my)?0xff000000:0xffffffff;}BitmapDrawable d=new BitmapDrawable(getResources(),Bitmap.createBitmap(px,n,n,Bitmap.Config.ARGB_8888));d.setFilterBitmap(false);d.setAntiAlias(false);qr.setImageDrawable(d);qr.setScaleType(ImageView.ScaleType.FIT_CENTER);qr.setContentDescription("QR-код для підключення TV");qr.setVisibility(View.VISIBLE);}
 private void hideQr(){qr.setImageDrawable(null);qr.setVisibility(View.GONE);}
 @Override protected void onDestroy(){destroyed=true;generation++;main.removeCallbacksAndMessages(null);io.shutdownNow();super.onDestroy();}
}
